# ===================================================================
# Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
# Des: Load and check the shared settings file
# Flo: defaults > file values > env overrides > expand ~ > check numbers > check power cmd
# I/O: config file (env, aa-conf-main.env) > globals set, or exit 1 with a clear message
# Run: bash ~/zz-base-home/as-apps/os-syst/ss-star-shut/cf-conf-load.sh --check
# ===================================================================
declare -gA CF_CONF=([keyz]="WORK_PATH CLOU_PATH DOWN_PATH FILE_MANA CHRO_BINA CHRO_DATA CHRO_PROF CODE_BINA CMDR_BINA CMDR_PORT CMDR_DBGP AISV_WDOG AISV_PORT AISV_VENV AISV_VPORT SYNC_BINA POWE_CMDZ COUN_SECO WAIT_SECO OPEN_GAPS SKIP_LIST GUAR_HUBP GUAR_ARMH GUAR_FORC GUAR_STAL GUAR_SELF GUAR_TERM GUAR_FLAG GUAR_STAT" [pathz]="WORK_PATH CLOU_PATH DOWN_PATH CHRO_DATA CMDR_BINA AISV_WDOG AISV_VENV SYNC_BINA GUAR_FLAG GUAR_STAT" [numz]="CMDR_PORT CMDR_DBGP AISV_PORT AISV_VPORT COUN_SECO WAIT_SECO OPEN_GAPS GUAR_HUBP GUAR_ARMH GUAR_FORC GUAR_STAL")
conf_dirz=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
conf_defa() { WORK_PATH=~/00_modules; CLOU_PATH=""; DOWN_PATH=~/Downloads; FILE_MANA=nemo; CHRO_BINA=google-chrome; CHRO_DATA=~/.config/chrome-launchers; CHRO_PROF=""; CODE_BINA=code; CMDR_BINA=""; CMDR_PORT=3030; CMDR_DBGP=9333; AISV_WDOG=""; AISV_PORT=3010; AISV_VENV=""; AISV_VPORT=3011; SYNC_BINA=""; POWE_CMDZ="systemctl poweroff"; COUN_SECO=9; WAIT_SECO=8; OPEN_GAPS=3; SKIP_LIST=""; GUAR_HUBP=3030; GUAR_ARMH=23; GUAR_FORC=2; GUAR_STAL=3; GUAR_SELF="linu-shut-nigh"; GUAR_TERM="gnome-terminal --"; GUAR_FLAG=~/.cmd-run/shutdown-armed; GUAR_STAT=~/.cmd-run/task-state; }
conf_read() { local line num=0 key val; while IFS= read -r line || [[ -n $line ]]; do num=$((num + 1)); line=${line%$'\r'}; [[ -z ${line//[[:space:]]/} || $line =~ ^[[:space:]]*# ]] && continue; [[ $line =~ ^([A-Z_]+)=(.*)$ ]] || { echo "config line $num: bad syntax" >&2; return 1; }; key=${BASH_REMATCH[1]}; val=${BASH_REMATCH[2]}; [[ " ${CF_CONF[keyz]} " == *" $key "* ]] || { echo "config line $num: unknown key $key" >&2; return 1; }; val=${val#\"}; val=${val%\"}; printf -v "$key" '%s' "$val"; done < "$1"; }
conf_expa() { local key val; for key in ${CF_CONF[pathz]}; do val=${!key}; val=${val/#\~/$HOME}; val=${val//\$\{HOME\}/$HOME}; printf -v "$key" '%s' "$val"; done; }
conf_chek() { local key; for key in ${CF_CONF[numz]}; do [[ ${!key} =~ ^(0|[1-9][0-9]*)$ ]] || { echo "config: $key must be a whole number without leading zeros, got '${!key}'" >&2; return 1; }; done; ((GUAR_ARMH <= 23)) || { echo "config: GUAR_ARMH must be 0..23, got '$GUAR_ARMH'" >&2; return 1; }; ((GUAR_FORC <= 23)) || { echo "config: GUAR_FORC must be 0..23, got '$GUAR_FORC'" >&2; return 1; }; [[ -n $POWE_CMDZ ]] || { echo "config: POWE_CMDZ must not be empty" >&2; return 1; }; }
conf_load() { local file="${1:-$conf_dirz/aa-conf-main.env}" key; local -A envv=(); [[ -r $file ]] || { echo "config: cannot read $file" >&2; return 1; }; for key in ${CF_CONF[keyz]}; do [[ -v $key ]] && envv[$key]=${!key}; done; conf_defa; conf_read "$file" || return 1; for key in "${!envv[@]}"; do printf -v "$key" '%s' "${envv[$key]}"; done; conf_expa; conf_chek; }
conf_show() { local key; for key in ${CF_CONF[keyz]}; do printf '  %-9s = %s\n' "$key" "${!key}"; done; }
if [[ ${BASH_SOURCE[0]} == "$0" ]]; then case "${1:-}" in --check|status) conf_load "${2:-}" || exit 1; echo "config OK"; conf_show; exit 0 ;; *) echo "Use: $0 --check [file]" >&2; exit 2 ;; esac; fi
